#!/usr/bin/env bash
# tests/graster_probe.sh - builds tests/graster_probe.s (CLI executable, case tables generated by
# tests/graster_check.py), writes it with a startup-sequence that runs it on a bootable OFS disk, boots the disk in
# an Amiberry session, reads the probe's output buffer through gdb (its bounds are printed on the serial port
# before "GRP fin") into <out_dir>/graster.txt and checks it with tests/graster_check.py (one PASS/FAIL line per vector). Expected values:
# docs/analysis/graphics-raster-v34.md §8, with this ROM's deliberate differences (docs/PLAN.md, rank 10).
#
# Usage: tests/graster_probe.sh <out_dir> [rom=build/kick13-prod.rom]
# The Commodore ROM is refused by amiberry-session unless GRP_ANALYSIS=1 (analysis agent only, see CLAUDE.md).
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="${1:?out_dir}"; ROM="${2:-$ROOT/build/kick13-prod.rom}"
A="$ROOT/.claude/skills/amiberry/scripts/amiberry-session"
mkdir -p "$OUT"
python3 -I "$ROOT/tests/graster_check.py" gen "$OUT/graster_cases.i" || exit 2
vasmm68k_mot -Fhunkexe -kick1hunks -nosym -m68000 -quiet -I "$OUT" -o "$OUT/graster_probe" \
  "$ROOT/tests/graster_probe.s" || exit 2
printf 'df0:graster_probe\n' > "$OUT/startup"
ADF="$OUT/graster_$$.adf"; rm -f "$ADF"
xdftool "$ADF" create + format Probe ofs + boot install + makedir s + write "$OUT/startup" s/startup-sequence \
  + write "$OUT/graster_probe" graster_probe >/dev/null || { echo "xdftool failed"; exit 2; }
NAME="${GRP_NAME:-grp$$}"
EXTRA=(); DIR="$ROOT/build/amiberry/sessions/$NAME"
[ "${GRP_ANALYSIS:-0}" = 1 ] && { EXTRA=(--analysis); DIR="$ROOT/build/amiberry/analysis/$NAME"; }
"$A" start --name "$NAME" --rom "$ROM" --adf "$ADF" --timeout 120 "${EXTRA[@]}" || exit 2
"$A" wait-serial "$NAME" "GRP fin" 600; RC=$?
if [ $RC = 0 ]; then
  BUF=$(tr -d '\r' < "$DIR/serial.log" | grep -a -m1 -o 'GRP buf=[0-9A-F]\{8\} end=[0-9A-F]\{8\}$')
  S=${BUF#GRP buf=}; S=${S%% *}; E=${BUF##*end=}
  [ -n "$BUF" ] && "$A" gdb "$NAME" -ex "dump binary memory $OUT/graster.bin 0x$S 0x$E" >/dev/null
  tr -d '\r' < "$OUT/graster.bin" | sed -n '/^GRP debut/,/^GRP fin/p' > "$OUT/graster.txt"
fi
"$A" stop "$NAME" >/dev/null
[ $RC = 0 ] || { echo "no GRP fin (timeout)"; exit 1; }
[ -s "$OUT/graster.txt" ] || { echo "output buffer not read"; exit 1; }
python3 -I "$ROOT/tests/graster_check.py" check "$OUT/graster.txt" > "$OUT/graster_check.txt"; RC=$?
grep -v '^PASS' "$OUT/graster_check.txt"
exit $RC
